 "content": "from collections import Counter


def transform(grid):
    """Restore cells masked with zero in a column-periodic sequence grid."""
    h, w = len(grid), len(grid[0])
    # Each column follows the same cyclic sequence; its diagonal is shifted
    # back by one sequence position. Ignore the diagonal when learning it.
    base = []
    for c in range(w):
        counts = Counter(grid[r][c] for r in range(h)
                         if grid[r][c] != 0 and r != c)
        if not counts:
            counts = Counter(grid[r][c] for r in range(h) if grid[r][c] != 0)
        base.append(counts.most_common(1)[0][0])

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                out[r][c] = base[c]
            if r == c:
                # The diagonal uses the predecessor in the repeating sequence.
                # Its value is visible elsewhere in the preceding column.
                out[r][c] = base[c - 1] if c > 0 else base[-1]
    return out

if __name__ == '__main__':
    import sys, json
    print(json.dumps(transform(json.load(sys.stdin)))
