    """Fill masked cells in a cyclic-number grid with its triangular pattern."""
    h, w = len(grid), len(grid[0])
    # The upper triangle follows a cyclic sequence starting at the first cell;
    # below the diagonal that sequence is advanced by one position.
    period = max(max(row) for row in grid)
    first = grid[0][0]

    def sequence(col):
        return (first - 1 + col) % period + 1

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                out[r][c] = sequence(c + (1 if c < r else 0))
    return out

